package workerpool

import "sync"

// Job holds input for a worker.
type Job struct {
	ID    int
	Input int
}

// Result holds output from a worker.
type Result struct {
	JobID  int
	Output int
}

// RunPool starts numWorkers goroutines that double each job's Input.
// It returns all results.
func RunPool(jobs []Job, numWorkers int) []Result {
	jobCh := make(chan Job, len(jobs))
	resCh := make(chan Result, len(jobs))

	var wg sync.WaitGroup
	for i := 0; i < numWorkers; i++ {
		go func() {
			for j := range jobCh { // bug: was 'for { j := Job{}' (never receives)
				_ = j
				// bug: result not sent
			}
			// bug: wg.Done() missing
		}()
	}

	for _, j := range jobs {
		jobCh <- j
	}
	close(jobCh)
	wg.Wait()

	close(resCh)
	var results []Result
	for r := range resCh {
		results = append(results, r)
	}
	return results
}

