package workerpool

import (
	"sort"
	"testing"
)

func TestRunPoolBasic(t *testing.T) {
	jobs := []Job{{ID: 1, Input: 5}, {ID: 2, Input: 10}, {ID: 3, Input: 3}}
	results := RunPool(jobs, 2)
	if len(results) != 3 {
		t.Fatalf("want 3 results, got %d", len(results))
	}
	sort.Slice(results, func(i, j int) bool { return results[i].JobID < results[j].JobID })
	if results[0].Output != 10 || results[1].Output != 20 || results[2].Output != 6 {
		t.Fatalf("unexpected outputs: %+v", results)
	}
}

func TestRunPoolSingleWorker(t *testing.T) {
	jobs := []Job{{ID: 1, Input: 7}}
	results := RunPool(jobs, 1)
	if len(results) != 1 || results[0].Output != 14 {
		t.Fatalf("want [{1 14}], got %+v", results)
	}
}

func TestRunPoolEmpty(t *testing.T) {
	results := RunPool(nil, 3)
	if len(results) != 0 {
		t.Fatalf("want empty, got %+v", results)
	}
}
